<?php namespace DomainSystem\Plugins\pages\Repositories; use DomainSystem\Plugins\Database\Connection; use DomainSystem\Plugins\pages\Contracts\PageRepositoryInterface; class SqlitePageRepository implements PageRepositoryInterface { private \PDO $db; public function __construct(Connection $connection) { $this->db = $connection->getPdo(); } public function getAll(): array { $stmt = $this->db->query("SELECT * FROM pages ORDER BY created_at DESC"); return $stmt->fetchAll(\PDO::FETCH_ASSOC); } public function findById(int $id): ?array { $stmt = $this->db->prepare("SELECT * FROM pages WHERE id = :id LIMIT 1"); $stmt->execute([":id" => $id]); $result = $stmt->fetch(\PDO::FETCH_ASSOC); return $result ?: null; } public function findBySlug(string $slug): ?array { $stmt = $this->db->prepare("SELECT * FROM pages WHERE slug = :slug LIMIT 1"); $stmt->execute([":slug" => $slug]); $result = $stmt->fetch(\PDO::FETCH_ASSOC); return $result ?: null; } public function create(array $data): void { $fields = implode(", ", array_keys($data)); $placeholders = ":" . implode(", :", array_keys($data)); $stmt = $this->db->prepare("INSERT INTO pages ($fields) VALUES ($placeholders)"); $params = []; foreach ($data as $k => $v) { $params[":$k"] = $v; } $stmt->execute($params); } public function update(int $id, array $data): void { $sets = []; $params = [":id" => $id]; foreach ($data as $k => $v) { $sets[] = "$k = :$k"; $params[":$k"] = $v; } $setString = implode(", ", $sets); $stmt = $this->db->prepare("UPDATE pages SET $setString WHERE id = :id"); $stmt->execute($params); } public function delete(int $id): void { $stmt = $this->db->prepare("DELETE FROM pages WHERE id = :id"); $stmt->execute([":id" => $id]); } }
